package me.easytransport.storage;
import me.easytransport.EasyTransportPlugin; import me.easytransport.model.Stop; import me.easytransport.model.StoredLocation; import me.easytransport.model.TransportType; import org.bukkit.Location; import org.bukkit.configuration.ConfigurationSection; import org.bukkit.entity.Villager; import java.util.*;
public final class TransportDataStore { private final EasyTransportPlugin plugin; public TransportDataStore(EasyTransportPlugin plugin){this.plugin=plugin;}
public void saveCashier(TransportType t,Villager v){String p="cashiers."+t.key();plugin.getConfig().set(p+".uuid",v.getUniqueId().toString());writeLocation(p+".location",v.getLocation());plugin.saveConfig();} public StoredLocation getCashierLocation(TransportType t){return readLocation("cashiers."+t.key()+".location");} public UUID getCashierUuid(TransportType t){String r=plugin.getConfig().getString("cashiers."+t.key()+".uuid");if(r==null)return null;try{return UUID.fromString(r);}catch(Exception e){return null;}} public void removeCashier(TransportType t){plugin.getConfig().set("cashiers."+t.key(),null);plugin.saveConfig();} public void removeAllCashiers(){plugin.getConfig().set("cashiers",null);plugin.getConfig().set("cashiers",new LinkedHashMap<>());plugin.saveConfig();}
public void saveBetween(TransportType t,Location l){writeLocation("between-teleports."+t.key(),l);plugin.saveConfig();} public StoredLocation getBetween(TransportType t){return readLocation("between-teleports."+t.key());} public void removeBetween(TransportType t){plugin.getConfig().set("between-teleports."+t.key(),null);plugin.saveConfig();}
public void saveStop(Stop s){String p="stops."+s.regionId()+"."+s.transport().key()+"."+cityKey(s.cityName());plugin.getConfig().set(p+".name",s.cityName());writeLocation(p+".location",s.location());plugin.saveConfig();plugin.refreshPl3xMap();} public void removeStop(String r,TransportType t,String c){plugin.getConfig().set("stops."+r+"."+t.key()+"."+cityKey(c),null);plugin.saveConfig();plugin.refreshPl3xMap();}
public List<Stop> getStops(String r,TransportType t){List<Stop> out=new ArrayList<>();ConfigurationSection sec=plugin.getConfig().getConfigurationSection("stops."+r+"."+t.key());if(sec==null)return out;for(String k:sec.getKeys(false)){String n=sec.getString(k+".name");StoredLocation l=readLocation(sec.getCurrentPath()+"."+k+".location");if(n!=null&&l!=null)out.add(new Stop(r,n,t,l));}out.sort(Comparator.comparing(Stop::cityName,String.CASE_INSENSITIVE_ORDER));return out;} public Stop findStop(String r,TransportType t,String c){for(Stop s:getStops(r,t))if(s.cityName().equalsIgnoreCase(c))return s;return null;} public void removeAllStops(){plugin.getConfig().set("stops",null);plugin.getConfig().set("stops",new LinkedHashMap<>());plugin.saveConfig();plugin.refreshPl3xMap();} public boolean hasStopsInWorld(String w){for(String r:getRegionIds())for(TransportType t:TransportType.values())for(Stop s:getStops(r,t))if(s.location().world().equalsIgnoreCase(w))return true;return false;} public Set<String> getRegionIds(){ConfigurationSection s=plugin.getConfig().getConfigurationSection("regions");return s==null?Set.of():s.getKeys(false);} public String getRegionName(String id){return plugin.getConfig().getString("regions."+id+".name",id);} public String findRegionId(String in){if(in==null)return null;for(String id:getRegionIds())if(id.equalsIgnoreCase(in)||getRegionName(id).equalsIgnoreCase(in))return id;return null;}
private String cityKey(String c){return c.toLowerCase(Locale.ROOT).replaceAll("[^a-zа-я0-9]+","_").replaceAll("_+","_");} private void writeLocation(String p,Location l){plugin.getConfig().set(p+".world",l.getWorld().getName());plugin.getConfig().set(p+".x",l.getX());plugin.getConfig().set(p+".y",l.getY());plugin.getConfig().set(p+".z",l.getZ());plugin.getConfig().set(p+".yaw",(double)l.getYaw());plugin.getConfig().set(p+".pitch",(double)l.getPitch());} private void writeLocation(String p,StoredLocation l){plugin.getConfig().set(p+".world",l.world());plugin.getConfig().set(p+".x",l.x());plugin.getConfig().set(p+".y",l.y());plugin.getConfig().set(p+".z",l.z());plugin.getConfig().set(p+".yaw",(double)l.yaw());plugin.getConfig().set(p+".pitch",(double)l.pitch());} private StoredLocation readLocation(String p){String w=plugin.getConfig().getString(p+".world");if(w==null||!plugin.getConfig().contains(p+".x"))return null;return new StoredLocation(w,plugin.getConfig().getDouble(p+".x"),plugin.getConfig().getDouble(p+".y"),plugin.getConfig().getDouble(p+".z"),(float)plugin.getConfig().getDouble(p+".yaw"),(float)plugin.getConfig().getDouble(p+".pitch"));}}
